doc=App.getDocument("hook_lesson5")
for o in doc.Objects:
    print(o.Name,o.TypeId,o.Label)
    if o.TypeId=="Spreadsheet::Sheet":
        for c in sorted(o.getUsedCells() if hasattr(o,'getUsedCells') else []):
            print("  ",c,o.getContents(c), o.get(c) if o.getContents(c) else '')
        print(" alias:",[(c,o.getAlias(c)) for c in o.getUsedCells() if o.getAlias(c)])
    print("  exprs:",o.ExpressionEngine)
    if hasattr(o,'Shape') and not o.Shape.isNull(): print("  vol",o.Shape.Volume,o.Shape.BoundBox)

